import React from 'react';

const Partners = () => {
    const partnersList = [
        "Partner 1",
        "Partner 2",
        "Partner 3",
        "Partner 4",
        "Partner 5"
    ];

    return (
        <div>
            <h1>Our Partners</h1>
            <ul>
                {partnersList.map((partner, index) => (
                    <li key={index}>{partner}</li>
                ))}
            </ul>
        </div>
    );
};

export default Partners;
